using System.ComponentModel.DataAnnotations;
public class UserDto { public int UserId { get; set; } public string FullName { get; set; } = ""; public string Email { get; set; } = ""; public string Role { get; set; } = ""; public string PhoneNumber { get; set; } = ""; public string? ProfilePictureUrl { get; set; } }
public class LoginVm { [Required, EmailAddress] public string Email { get; set; } = ""; [Required] public string Password { get; set; } = ""; }
public class RegisterVm { [Required, StringLength(101, MinimumLength = 3)] public string FullName { get; set; } = ""; [Required, EmailAddress] public string Email { get; set; } = ""; [Required, StringLength(100, MinimumLength = 8)] public string Password { get; set; } = ""; [Required] public string Role { get; set; } = "Participant"; [Required] public string PhoneNumber { get; set; } = ""; public string? OrganiserCode { get; set; } }
public class EventDto { public int EventId { get; set; } public string Name { get; set; } = ""; public string Description { get; set; } = ""; public DateTime EventDate { get; set; } public string Location { get; set; } = ""; public double DistanceKm { get; set; } public int EventTypeId { get; set; } public string EventType { get; set; } = ""; public int OrganiserId { get; set; } public string OrganiserName { get; set; } = ""; public string? BannerUrl { get; set; } public int? EnrolmentCount { get; set; } public List<CategoryDto>? Categories { get; set; } }
public class CategoryDto { public int CategoryId { get; set; } public int EventId { get; set; } public string Name { get; set; } = ""; public string Description { get; set; } = ""; public int? MinAge { get; set; } public int? MaxAge { get; set; } public string AgeRange { get; set; } = ""; public double DistanceKm { get; set; } }
public class EnrolmentDto { public int EnrolmentId { get; set; } public int EventId { get; set; } public string EventName { get; set; } = ""; public DateTime EventDate { get; set; } public int CategoryId { get; set; } public string CategoryName { get; set; } = ""; public string Status { get; set; } = ""; public DateTime EnrolmentDate { get; set; } public string ParticipantName { get; set; } = ""; public string ParticipantEmail { get; set; } = ""; public int UserId { get; set; } }
public class ResultDto { public int ResultId { get; set; } public int EnrolmentId { get; set; } public int EventId { get; set; } public string EventName { get; set; } = ""; public DateTime EventDate { get; set; } public string CategoryName { get; set; } = ""; public string ParticipantName { get; set; } = ""; public TimeSpan FinishTime { get; set; } public int FinishPosition { get; set; } public int TotalFinishers { get; set; } }
public class EventVm { public int EventId { get; set; } [Required] public string Name { get; set; } = ""; [Required] public string Description { get; set; } = ""; [Required] public DateTime EventDate { get; set; } = DateTime.Today.AddDays(30); [Required] public string Location { get; set; } = ""; [Range(.1, 1000)] public double DistanceKm { get; set; } = 5; [Range(1, 3)] public int EventTypeId { get; set; } = 1; public IFormFile? Banner { get; set; } }
public class CategoryVm { [Required] public string Name { get; set; } = ""; [Required] public string Description { get; set; } = ""; public int? MinAge { get; set; } public int? MaxAge { get; set; } [Range(.1, 1000)] public double DistanceKm { get; set; } = 5; }
public class ResultVm { public int EnrolmentId { get; set; } [Range(1, 86399)] public int FinishTimeSeconds { get; set; } [Range(1, int.MaxValue)] public int FinishPosition { get; set; } [Range(1, int.MaxValue)] public int TotalFinishers { get; set; } }
